mapper.select:
select t.id, t.org_id as orgId, t.signature_id as signatureId, ss.sign_name as signName, t.template_name as templateName, t.template_content as templateContent, t.template_item as templateItem, t.template_code as templateCode, t.template_status as templateStatus, t.template_type as templateType, t.template_length as templateLength, t.remark, t.sense, t.crt_user as crtUser from sms_template_set t left join sms_signature_set ss on t.signature_id=ss.id
and t.template_code = #{queryForm.templateCode}
and t.template_type = #{queryForm.templateType}
and t.org_id = #{queryForm.orgId}
and t.template_name = #{queryForm.templateName}
and t.template_status = #{queryForm.templateStatus}
and t.sense = #{queryForm.sense}

select sa.id, sa.org_id as orgId, sa.signature_id as signatureId, ss.sign_name as signName, sa.template_name as templateName, sa.template_content as templateContent, sa.template_item as templateItem, sa.template_code as templateCode, sa.template_status as templateStatus, sa.remark, sa.sense, sa.crt_user as crtUser, t.status as sendEnable from sms_autosend_event t left join sms_template_set sa on sa.id=t.template_id left join sms_signature_set ss on sa.signature_id=ss.id
t.event_code = #{eventCode}
and t.org_id = #{orgId}
